#!/usr/bin/env python3
"""Package accepted actual generated bytes; never fill or edit fixture JSON.

This produces a reviewable artifact. Only a separately approved sources.json
pointer can activate it. --check repeats packaging, not historical EELS filling.
"""
from __future__ import annotations

import argparse
from collections import Counter
import json
from pathlib import Path
import subprocess
import sys
import fixture_corrections as F


def git(root, *args):
    return subprocess.check_output(["git", "-C", str(root), *args])


def verify_source(root, acceptance, generation, patch):
    identity = generation["source_before"]
    F.need(identity == generation["source_after"] and generation["completed"] and
           generation["source_stable"] and not identity["tracked_status"], "generation source receipt differs")
    F.need(identity["commit"] == acceptance["source_commit"] and identity["tree"] == acceptance["source_tree"],
           "accepted source receipt identity differs")
    base = "1562e2f8b5cb1efda7e0d7c517f2dfb5742c0a43"
    F.need(git(root, "rev-parse", "HEAD").decode().strip() == identity["commit"] and
           git(root, "rev-parse", "HEAD^{tree}").decode().strip() == identity["tree"] and
           not git(root, "status", "--porcelain=v1", "--untracked-files=no").strip(), "generation checkout no longer matches")
    changed = git(root, "diff", "--name-only", base, "HEAD").decode().splitlines()
    F.need(changed == [F.SOURCE], "generation source has extra changed paths")
    F.need(git(root, "diff", base, "HEAD", "--", F.SOURCE) == patch, "generation source patch differs")
    original = git(root, "show", base + ":" + F.SOURCE)
    corrected = F.regular_bytes(root / F.SOURCE)
    F.need(F.digest(original) == "c86674da31d6b4c2938676f1eeac4d323b043e1e714d1bef68faaa5d87ba5300" and
           F.digest(corrected) == "49071d1a91c9599123adeef70226db165fc47288aebf90c77b5eb29b3220d1a5" and
           F.digest(corrected) == identity["test_source_sha256"], "unreviewed generation source bytes")
    F.need(F.sha(root / "uv.lock") == identity["uv_lock_sha256"], "generation environment lock differs")
    mode = git(root, "ls-tree", "HEAD", "--", F.SOURCE).decode().split()[0]
    F.need(mode == "100644", "generation source mode differs")
    return {"base_commit": base, "base_tree": git(root, "rev-parse", base + "^{tree}").decode().strip(),
        "commit": identity["commit"], "tree": identity["tree"], "path": F.SOURCE,
        "before_blob": git(root, "rev-parse", base + ":" + F.SOURCE).decode().strip(),
        "after_blob": git(root, "rev-parse", "HEAD:" + F.SOURCE).decode().strip(),
        "before_sha256": F.digest(original), "after_sha256": F.digest(corrected), "mode": mode,
        "patch_sha256": F.digest(patch)}


def package_bytes(base_root, experiment_receipt, sources):
    experiment = experiment_receipt.parent
    acceptance = F.read(experiment_receipt)
    F.need(acceptance.get("accepted") is True, "experiment is not accepted")
    manifest_raw = F.regular_bytes(experiment / "artifacts.json")
    F.need(F.digest(manifest_raw) == acceptance["artifact_manifest_sha256"], "accepted experiment manifest hash differs")
    manifest = F.parse(manifest_raw)
    F.need(manifest["schema"] == "jaune-amsterdam-isolated-experiment-evidence-v1" and
           len(manifest["artifacts"]) == manifest["artifact_count"] == acceptance["retained_artifact_hashes_verified"],
           "accepted experiment inventory differs")
    evidence = []
    for artifact in manifest["artifacts"]:
        relative = str(F.relative(artifact["relative_path"]))
        path = F.repo_file(experiment, relative)
        raw = F.regular_bytes(path)
        F.need(F.digest(raw) == artifact["sha256"] and len(raw) == artifact["bytes"],
               "accepted experiment artifact hash differs: " + relative)
        evidence.append({"path": relative, "sha256": F.digest(raw), "bytes": len(raw)})
    F.need(F.sha(experiment / "report.md") == acceptance["report_sha256"], "accepted experiment report hash differs")
    corrected_generation = F.read(experiment / "runtime-corrected/generation.json")
    baseline_generation = F.read(experiment / "runtime-baseline/generation.json")
    root = Path(corrected_generation["source_before"]["root"])
    patch = F.regular_bytes(experiment / "applied.patch")
    source = verify_source(root, acceptance, corrected_generation, patch)
    F.need(baseline_generation["completed"] and baseline_generation["source_stable"] and
           baseline_generation["source_before"]["commit"] == source["base_commit"] and
           baseline_generation["source_before"] == baseline_generation["source_after"] and
           baseline_generation["source_before"]["root"] == str(root), "missing exact same-checkout baseline")
    F.need(F.read(experiment / "comparison-two-phase.json")["ok"] and
           F.read(experiment / "comparison-ordinary.json")["ok"] and
           F.read(experiment / "original-decoder.json")["ok"] and
           F.read(experiment / "runtime-comparer-controls/controls.json")["ok"] and
           F.read(experiment / "runtime-source-control/control.json")["ok"] and
           F.read(experiment / "runtime-jaune/replays.json")["completed"], "missing successful experiment boundary receipts")
    observed_formats = {}
    for mode in ("two-phase", "ordinary"):
        old = {(row["format"], row["case_key"]): row for row in baseline_generation["emitted"][mode]["cases"]}
        new = {(row["format"], row["case_key"]): row for row in corrected_generation["emitted"][mode]["cases"]}
        F.need(set(old) == set(new) and bool(new), "generated format/case membership differs")
        observed_formats[mode.replace("-", "_")] = dict(Counter(fmt for fmt, _ in new))
        for (fmt, case), row in new.items():
            before_path, after_path = Path(old[(fmt, case)]["path"]), Path(row["path"])
            F.need(before_path.is_relative_to(experiment / ("runtime-baseline/fixtures-" + mode)) and
                   after_path.is_relative_to(experiment / ("runtime-corrected/fixtures-" + mode)), "generation format path escapes")
            F.need(F.sha(before_path) == old[(fmt, case)]["file_sha256"] and F.sha(after_path) == row["file_sha256"],
                   "generated format file identity differs")
            left, right = F.read(before_path)[case], F.read(after_path)[case]
            if fmt != "blockchain_test":
                F.need(F.canonical(F.semantic(left)) == F.canonical(F.semantic(right)), "Engine payload/API semantic drift")
            for value in (left, right):
                wanted = F.digest(json.dumps(F.semantic(value), sort_keys=True, separators=(",", ":")).encode())
                F.need(value["_info"]["hash"] == "0x" + wanted, "generated semantic metadata hash differs")
    handoff = F.read(experiment / "correction-artifacts.json")
    F.need(len(handoff["rows"]) == 2, "correction handoff population differs")
    fixtures = base_root / sources["amsterdam"]["fixtures_subpath"]
    entries, payloads = [], {}
    for row in handoff["rows"]:
        original = Path(row["original"])
        relative = original.relative_to(fixtures / "blockchain_tests").as_posix()
        generated = Path(row["generated_corrected"]["path"])
        baseline = Path(row["generated_baseline"]["path"])
        F.need(generated.is_relative_to(experiment / "runtime-corrected/fixtures-two-phase") and
               baseline.is_relative_to(experiment / "runtime-baseline/fixtures-two-phase"), "generated handoff escapes accepted outputs")
        raw = F.regular_bytes(generated)
        old = F.regular_bytes(original)
        F.need(F.sha(baseline) == row["generated_baseline"]["sha256"] and
               F.digest(raw) == row["generated_corrected"]["sha256"], "generation handoff output hash differs")
        case = F.CASE_PREFIX + Path(relative).stem + "[fork_" + F.NETWORK + "-blockchain_test]"
        entry = {"path": relative, "network": F.NETWORK, "case": case,
                 "original_sha256": row["original_sha256"], "generated_sha256": F.digest(raw),
                 "wire_sha256": row["original_wire_sha256"], "old": row["old_expectation"],
                 "new": row["new_expectation"], "metadata_changed_keys": row["metadata_changed_keys"]}
        F.verify_fixture_delta(old, raw, entry)
        F.need(F.canonical(F.semantic(F.parse(old)[case])) ==
               F.canonical(F.semantic(F.read(baseline)[case])), "generated baseline differs from original semantics")
        entries.append(entry)
        payloads["fixtures/blockchain_tests/" + relative] = raw
    entries.sort(key=lambda e: e["path"])
    F.validate_entries(entries)
    initial_env = json.loads(F.read(experiment / "environment-metadata-command.json")["output"])
    final_env = F.parse(F.regular_bytes(experiment / "environment-final.stdout"))
    F.need(initial_env == final_env, "generation environment metadata changed")
    replacements = [(str(experiment), "<EXPERIMENT>"), (str(root), "<GENERATION_CHECKOUT>"),
        (str(experiment.parent / "codex-amsterdam-repair-design"), "<EXPERIMENT_DESIGN>"),
        (str(base_root), "<BASE_INSTALL>"),
        (F.read(experiment / "runtime-jaune/replays.json")["facts"]["source_root"], "<JAUNE_CHECKOUT>")]
    def portable(value):
        for prefix, token in replacements:
            value = value.replace(prefix, token)
        F.need("/Users/" not in value and "/home/" not in value, "unmapped generation command location")
        return value
    commands = []
    for artifact in evidence:
        if artifact["path"].endswith(".command.json"):
            command = F.read(experiment / artifact["path"])
            commands.append({"record": artifact["path"], "argv": [portable(a) for a in command["argv"]],
                "cwd": portable(command["cwd"]), "exit": command["exit"],
                "started_utc": command["started_utc"], "timing_scope": "Mac local only",
                "stdout_sha256": command["stdout"]["sha256"], "stderr_sha256": command["stderr"]["sha256"]})
    receipt = {"kind": "jaune-correction-generation-receipt-v1", "id": F.ID, "source": source,
        "environment": {"uv_lock_sha256": corrected_generation["source_before"]["uv_lock_sha256"],
            "python": initial_env["python"], "packages": initial_env["packages"],
            "files": [{"role": Path(a["path"]).name, "sha256": a["sha256"], "bytes": a["bytes"]}
                      for a in F.read(experiment / "preparation-identities.json")["environment_files"]]},
        "evidence": {"experiment_manifest_sha256": F.digest(manifest_raw),
            "experiment_acceptance_sha256": F.sha(experiment_receipt),
            "accepted_report_sha256": acceptance["report_sha256"], "artifacts": evidence,
            "packager_sha256": F.sha(Path(__file__)), "verifier_sha256": F.sha(Path(F.__file__))},
        "commands": commands,
        "formats": {**observed_formats,
            "stateful": "help and explicit collection 2; helper selection tested; no payload fill",
            "sync": "filtered: selected tests have no verify_sync marker"},
        "limits": acceptance["limits"]}
    receipt_raw = F.canonical(receipt)
    base = F.base_identity(sources["amsterdam"])
    index = {"kind": F.KIND, "id": F.ID, "base": base,
             "generation_receipt_sha256": F.digest(receipt_raw), "entries": entries}
    index_raw = F.canonical(index)
    payloads["correction-index.json"] = index_raw
    archive = F.archive_bytes(payloads)
    registration = {**index, "source_patch_sha256": F.digest(patch),
        "archive_sha256": F.digest(archive), "archive_size_bytes": len(archive), "index_sha256": F.digest(index_raw)}
    F.verify_receipt(receipt_raw, registration)
    return {"registration.json": F.canonical(registration), "generation-receipt.json": receipt_raw,
            "source.patch": patch, "artifact.tar.gz": archive}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--base-root", type=Path, required=True)
    parser.add_argument("--experiment-receipt", type=Path, required=True)
    parser.add_argument("--sources", type=Path, default=F.SCRIPTS / "sources.json")
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)
    try:
        sources = F.load_sources(args.sources)
        pointer = sources["amsterdam"].get("fixture_correction")
        if pointer is not None:
            F.need(args.check, "new proposal packaging requires an inactive correction pointer")
            reg, directory = F.load_registration(pointer, args.sources.resolve().parent.parent)
            F.need(args.output.resolve() == directory.resolve(), "registered --check must target its exact registered package")
            package = F.verify_package(reg, directory)
            F.verify_base_bindings(package, sources["amsterdam"],
                                   args.base_root / sources["amsterdam"]["fixtures_subpath"])
        output = package_bytes(args.base_root, args.experiment_receipt, sources)
        if args.check:
            F.need(args.output.is_dir() and {p.name for p in args.output.iterdir()} == set(output), "stale correction package members")
            F.need(all(F.regular_bytes(args.output / name) == raw for name, raw in output.items()), "stale correction package bytes")
        else:
            F.need(not args.output.exists(), "correction output must be a new directory")
            args.output.mkdir(parents=True)
            for name, raw in output.items():
                (args.output / name).write_bytes(raw)
        reg = F.parse(output["registration.json"])
        F.verify_package(reg, args.output)
        print(f"OK — {'checked' if args.check else 'packaged'} explicit proposed correction {F.ID}; archive {reg['archive_sha256']}")
        return 0
    except (F.CorrectionError, OSError, KeyError, TypeError, ValueError, subprocess.CalledProcessError) as error:
        print(f"correction packaging error: {error}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
